import { Component } from '@angular/core';
import { WalletService } from 'src/app/_services';

@Component({
    selector: 'app-wallet-list',
    host: { class: 'childRouteFlex' },
    templateUrl: './wallet-list.component.html',
    styleUrls: ['./wallet-list.component.css']
})
export class WalletListComponent {
    constructor(public walletService: WalletService) {
        if (walletService.wallets.length == 0) {
            walletService.getWalletsFromServer().subscribe(() => {
				this.loading = false;
            });
        }
    }

	loading : boolean = true;
}
<div class="default-list-container">
    <div
        *ngIf="this.walletService.wallets.length === 0"
        class="empty-list-container"
    >
        <h1 class="text-center">...</h1>
        <br />
		<h6 *ngIf="loading" class="text-center">Loading Wallets</h6>
        <p *ngIf="loading" class="text-center">Please wait some time.</p>

        <h6 *ngIf="!loading" class="text-center">No wallets found.</h6>
        <p *ngIf="!loading" class="text-center">Create a new wallet to get started.</p>
        <br /><br />
    </div>
    <div class="default-list">
        <div
            class="default-editable-list-item"
            *ngFor="let wallet of this.walletService.wallets"
            [routerLink]="['/wallet', wallet.id]"
            (click)="this.walletService.selectWallet(wallet.id)"
        >
            <div>
                <p style="margin: 0">{{ wallet.name }}</p>
            </div>
            <div>
                <div class="text-end amount-value" [ngClass]="{
                    'positive-amount': wallet.amount > 0,
                    'negative-amount': wallet.amount < 0
                }">
                    {{ wallet.amount }}
                </div>
                <div class="text-end">
                    {{ wallet.currencyCode }}
                </div>
            </div>
        </div>
    </div>
</div>
